steps.starter:
ROOMS = {
    "hall": {
        "name": "Hall",
        "desc": "A dusty hall with a grand staircase.",
        "exits": {"north": "library", "east": "kitchen"},
        "items": ["lamp"],
    },
    "library": {
        "name": "Library",
        "desc": "Shelves of old books line the walls.",
        "exits": {"south": "hall"},
        "items": ["key", "book"],
    },
    "kitchen": {
        "name": "Kitchen",
        "desc": "It smells of old bread. A trapdoor leads down.",
        "exits": {"west": "hall", "down": "cellar"},
        "items": [],
    },
    "cellar": {
        "name": "Cellar",
        "desc": "Dark and damp. Something glints in the corner.",
        "exits": {"up": "kitchen"},
        "items": ["treasure"],
        "locked": True,
    },
}

DIRECTIONS = {"n": "north", "s": "south", "e": "east", "w": "west", "u": "up", "d": "down"}
ALIASES = {"l": "look", "q": "quit", "i": "inventory", "get": "take"}
FILLER = {"the", "to", "a", "an"}


def parse(line):
    words = [w for w in line.lower().split() if w not in FILLER]
    if not words:
        return "", ""
    verb, *rest = words
    verb = ALIASES.get(verb, verb)
    verb = DIRECTIONS.get(verb, verb)
    if verb in DIRECTIONS.values():
        return "go", verb
    noun = " ".join(rest)
    if verb == "go":
        noun = DIRECTIONS.get(noun, noun)
    return verb, noun


def read_command():
    try:
        return parse(input())
    except EOFError:
        return "quit", ""


def describe(room_id):
    room = ROOMS[room_id]
    print(f"== {room['name']} ==")
    print(room["desc"])
    if room["items"]:
        print("You see: " + ", ".join(sorted(room["items"])))
    print("Exits: " + ", ".join(sorted(room["exits"])))


def take(room, inventory, item):
    if item in room["items"]:
        room["items"].remove(item)
        inventory.append(item)
        print(f"Taken {item}.")
    else:
        print(f"There is no {item} here.")


def drop(room, inventory, item):
    if item in inventory:
        inventory.remove(item)
        room["items"].append(item)
        print(f"Dropped {item}.")
    else:
        print(f"You don't have {item}.")


def move(state, direction):
    room = ROOMS[state["room"]]
    if direction not in room["exits"]:
        print("You can't go that way.")
        return
    target_id = room["exits"][direction]
    target = ROOMS[target_id]
    if target.get("locked"):
        if "key" not in state["inventory"]:
            print("The door is locked.")
            return
        target["locked"] = False
        print("You unlock the door with the key.")
    state["room"] = target_id
    state["moves"] += 1
    describe(target_id)


state = {"room": "hall", "inventory": [], "moves": 0}
describe(state["room"])
while True:
    verb, noun = read_command()
    room = ROOMS[state["room"]]
    match verb, noun:
        case "", _:
            continue
        case "look", "":
            describe(state["room"])
        case "go", "":
            print("Go where?")
        case "go", direction:
            move(state, direction)
        case ("take" | "drop"), "":
            print(f"{verb.capitalize()} what?")
        case "take", item:
            take(room, state["inventory"], item)
            if "treasure" in state["inventory"]:
                print(f"You win! Moves: {state['moves']}")
                break
        case "drop", item:
            drop(room, state["inventory"], item)
        case "inventory", "":
            print("You carry: " + (", ".join(sorted(state["inventory"])) or "nothing") + ".")
        case "quit", _:
            print("Bye.")
            break
        case _:
            print("I don't understand.")
